import pytest
from candidate import is_palindrome, make_palindrome

class TestIsPalindrome:
    def test_is_palindrome_even_length(self):
        assert is_palindrome("abba") == True

    def test_is_palindrome_odd_length(self):
        assert is_palindrome("abc") == False

    def test_is_palindrome_single_character(self):
        assert is_palindrome("a") == True

    def test_is_palindrome_case_insensitive(self):
        assert is_palindrome("Abba") == True

    def test_is_palindrome_empty_string(self):
        assert is_palindrome("") == True

    def test_is_palindrome_non_palindrome(self):
        assert is_palindrome("hello") == False

class TestMakePalindrome:
    def test_make_palindrome_empty_string(self):
        assert make_palindrome("") == ""

    def test_make_palindrome_single_character(self):
        assert make_palindrome("a") == "a"

    def test_make_palindrome_two_characters(self):
        assert make_palindrome("a") == "aa"

    def test_make_palindrome_already_palindrome(self):
        assert make_palindrome("abba") == "abba"

    def test_make_palindrome_no_palindromic_suffix(self):
        assert make_palindrome("abc") == "acba"

    def test_make_palindrome_with_vowels(self):
        assert make_palindrome("ae") == "aeae"

    def test_make_palindrome_with_consonants(self):
        assert make_palindrome("bc") == "bcub"

    def test_make_palindrome_with_mixed_case(self):
        assert make_palindrome("AbC") == "AbCba"
